fn listing<T: std::fmt::Display>(c: Constant<T>, kind: &'static str) -> ConstantListing {
    ConstantListing {
        name: c.name,
        kind,
        unit: c.unit,
        value: c.value.to_string(),
        release: c.release,
        table: c.provenance.locator.table.clone(),
        range: c.provenance.locator.dataset_range.clone(),
        hash: c.hash,
        source: c.provenance,
    }
}

