        assert!(!r.value.contains(Interval::point(Ratio::int(0))));
        assert!(
            r.value.hi < Ratio::int(0),
            "CODATA −e/me is the signed electron quotient, not +e/me"
        );
        assert_eq!(r.hash, electron_charge_to_mass().hash);
