        let r = electron_g_factor();
        let scale = 10i128.pow(14);
        let lo = Ratio::new(-200_231_930_436_291, scale);
        let hi = Ratio::new(-200_231_930_436_221, scale);
        let centre = Ratio::new(-200_231_930_436_256, scale);
