        assert_eq!(r.value, Interval::new(lo, hi));
        assert_ne!(r.value.lo, r.value.hi, "mu_e_mmu is measured, not SI-exact");
        assert!(r.value.contains(Interval::point(centre)));
        assert!(!r.value.contains(Interval::point(Ratio::int(0))));
