        let c22 = Ratio::new(19_877, scale);
        assert!(
            !r.value.contains(Interval::point(c22)),
            "2018 hull excludes the CODATA 2022 last-digit 8770; stored centre stays 20200"
        );
        let d42 = Ratio::new(20_200, scale);
